"290 :   private boolean isVariableStillLiveWithinExpression(
291 :       Node n, Node exprRoot, String variable) {
292 :     while (n != exprRoot) {
293 :       for(Node sibling = n.getNext(); sibling != null;
294 :           sibling = sibling.getNext()) {
295 :         if (!ControlFlowGraph.isEnteringNewCfgNode(sibling)) {
296 :           VariableLiveness state = isVariableReadBeforeKill(sibling, variable);
297 : 
